Sure! Here's a JavaScript function that switches the order of adjectives:

```javascript
function switchAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  // Find the indices of the first adjective and the second adjective (if present)
  let firstAdjIndex = -1;
  let secondAdjIndex = -1;
  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {
      firstAdjIndex = i;
      break;
    }
  }
  for (let j = words.length - 1; j >= 0; j--) {
    if (isAdjective(words[j]) && j !== firstAdjIndex) {
      secondAdjIndex = j;
      break;
    }
  }

  // If we couldn't find two adjectives, return the original sentence
  if (firstAdjIndex === -1 || secondAdjIndex === -1) {
    return sentence;
  }

  // Swap the positions of the first and second adjectives
  const temp = words[firstAdjIndex];
  words[firstAdjIndex] = words[secondAdjIndex];
  words[secondAdjIndex] = temp;

  // Join the words back into a sentence
  return words.join(" ");
}

// Helper function to check if a word is an adjective
function isAdjective(word) {
  // This is a simple heuristic to identify common English adjectives
  // You could make it more sophisticated if needed
  return /^[a-z]+$/.test(word) && ["a", "an", "the"].indexOf(word.toLowerCase().slice(0, 2)) === -1;
}
```

Here's how you might use the function:

```javascript
const input = "Beautiful green trees are in the park.";
const output = switchAdjectives(input);
console.log(output); // Output: "Green beautiful trees are in the park."
``

